<script setup>
const props=defineProps({embedded:Boolean,navigationKey:String})
import {computed,nextTick,onMounted,reactive,ref} from 'vue'
import WorkspaceModal from './components/WorkspaceModal.vue'
import WorkspaceTabs from './components/WorkspaceTabs.vue'
import DataTable from './components/DataTable.vue'
import {Button as UiButton} from './components/ui/button'
import {Input as UiInput} from './components/ui/input'
import UiSelect from './components/ui/select/Select.vue'
import {Textarea as UiTextarea} from './components/ui/textarea'
import {useNoticeToast} from './use-toast'
import {call,setCSRF} from './api'
import {sidebarCollapsed} from './workspace'
import {unitLabel} from './units'
import {dismissOnBackdrop} from './dialogs'

const api=(name,args={},write=false)=>call('lotus_farm.timekeeping.'+name,args,write)
const periodApi=(name,args={},write=false)=>call('lotus_farm.hr_period.'+name,args,write)
// Day context from staff_day: public holiday / weekly off, whether a calendar exists, and the month lock.
const dayInfo=ref({holiday:null,has_calendar:true,period_closed:false}),machineBusy=ref(false)
const calendarInfo=ref(null),calendarYear=ref(0),weeklyOff=ref(['Sunday']),extraHolidays=ref([])
const weekdayLabels={Monday:'Thứ hai',Tuesday:'Thứ ba',Wednesday:'Thứ tư',Thursday:'Thứ năm',Friday:'Thứ sáu',Saturday:'Thứ bảy',Sunday:'Chủ nhật'}
const clock=v=>v?String(v).slice(11,16):'—'
function machineText(row){const p=row.machine;if(!p)return '';if(!p.checkins)return p.reason;return clock(p.in_time)+'–'+clock(p.out_time)+(p.late_entry?' · Muộn':'')+(p.early_exit?' · Về sớm':'')+(p.reason?' · '+p.reason:'')}
const session=ref(null),company=ref(''),date=ref(''),month=ref(''),shift=ref(''),farm=ref(''),tab=ref('staff'),search=ref('')
const busy=ref(false),saving=ref(false),error=ref(''),notice=ref(''),catalog=ref({farms:[],teams:[],shifts:[],genders:[],departments:[],uoms:[]})
const staff=ref([]),crews=ref([]),availableTeams=ref([]),monthData=ref(null),crewMonth=ref(null),eventId=ref(crypto.randomUUID())
const crewDialog=ref(null),masterDialog=ref(null),confirmDialog=ref(null),masterKind=ref('employee'),confirmation=ref(null),reason=ref('')
const crew=reactive({}),master=reactive({}),crewBaseline=ref('')
const crewSnapshot=()=>JSON.stringify(Object.fromEntries(['work_type','headcount','present','workdays','completed_qty','uom','unit_rate','rate_override_reason','notes'].map(f=>[f,crew[f]])))
const cap=computed(()=>session.value?.capabilities||{})
const dirty=computed(()=>staff.value.some(r=>r.edited))
const locked=computed(()=>!!dayInfo.value.period_closed)
const canEditStaff=computed(()=>!locked.value&&!!(cap.value.Attendance?.create||cap.value.Attendance?.write))
const selected=computed(()=>staff.value.filter(r=>r.selected))
const staffCounts=computed(()=>({people:staff.value.length,approved:staff.value.filter(r=>r.name&&r.docstatus===1).length,pending:staff.value.filter(r=>r.name&&r.docstatus===0).length,unknown:staff.value.filter(r=>!r.name).length}))
const genderLabel=name=>({Male:'Nam',Female:'Nữ',Other:'Khác',Transgender:'Chuyển giới',Genderqueer:'Phi nhị nguyên',"Prefer not to say":'Không khai báo'})[name]||name
const statuses={'Present':'Có mặt','Half Day':'Nửa ngày','Absent':'Vắng','Work From Home':'Làm từ xa','On Leave':'Nghỉ phép'}
const editableStatuses=Object.entries(statuses).filter(([key])=>key!=='On Leave')
const statusCode={'Present':'X','Half Day':'½','Absent':'V','Work From Home':'TX','On Leave':'P'}
const fmt=n=>Number(n||0).toLocaleString('vi-VN',{maximumFractionDigits:3})
const currency=computed(()=>session.value?.companies.find(c=>c.name===company.value)?.default_currency||'VND')
const cash=n=>Number(n||0).toLocaleString('vi-VN',{style:'currency',currency:currency.value})
const teamName=name=>catalog.value.teams.find(t=>t.name===name)?.team_name||name
const farmName=name=>catalog.value.farms.find(f=>f.name===name)?.farm_name||name
const state=n=>['Nháp','Đã duyệt','Đã hủy'][n]||'Chưa chấm'
const tabs=computed(()=>[{id:'staff',label:'Nhân sự chính thức',allowed:cap.value.Attendance?.read&&cap.value.Employee?.read},{id:'crew',label:'Đội khoán',allowed:cap.value['Lotus Crew Attendance']?.read},{id:'month',label:'Bảng công tháng',allowed:cap.value.Attendance?.read||cap.value['Lotus Crew Attendance']?.read},{id:'setup',label:'Nhân sự & thiết lập',allowed:true}].filter(t=>t.allowed))
const actions=computed(()=>[{id:'farm-work',label:'Công việc vườn',navigation:true,href:'/lotus/cong-viec'},{id:'home',label:'Trang chủ Lotus',navigation:true,href:'/lotus/mobile'},{id:'stock',label:'Quản lý kho',navigation:true,href:'/lotus/kho'},...tabs.value.map(t=>({...t,navigation:true,run:()=>chooseTab(t.id)})),{id:'hrms',label:'Hồ sơ nhân sự Lotus',navigation:true,href:'/lotus/nhan-su'},{id:'native',label:'Quản trị Frappe HRMS',navigation:true,href:'/desk/hr-setup'}])
let version=0
async function loadCatalog(){catalog.value=await api('catalogue',{company:company.value})}
async function load(){if(!company.value)return;const id=++version;busy.value=true;error.value=''
 try{
  if(tab.value==='staff'){const result=await api('staff_day',{company:company.value,date:date.value,shift:shift.value,search:search.value});if(id===version){staff.value=result.rows.map(r=>({...r,selected:false,edited:false,machine:null}));dayInfo.value={holiday:result.holiday,has_calendar:result.has_calendar,period_closed:result.period_closed};eventId.value=crypto.randomUUID()}}
  if(tab.value==='setup'&&session.value?.is_hr_manager){const result=await periodApi('calendar_info',{company:company.value,year:calendarYear.value});if(id===version){calendarInfo.value=result;loadCalendarForm(result)}}
  if(tab.value==='crew'){const result=await api('crew_day',{company:company.value,date:date.value,farm:farm.value});if(id===version){crews.value=result.rows;availableTeams.value=result.teams}}
  if(tab.value==='month'){
   const employeeResult=cap.value.Attendance?.read&&cap.value.Employee?.read?await api('monthly',{company:company.value,month:month.value}):null
   const teamResult=cap.value['Lotus Crew Attendance']?.read?await api('crew_monthly',{company:company.value,month:month.value,farm:farm.value}):null
   if(id===version){monthData.value=employeeResult;crewMonth.value=teamResult}
  }
 }catch(e){if(id===version)error.value=e.message}finally{if(id===version)busy.value=false}
}
async function init(){busy.value=true;try{session.value=await api('bootstrap');setCSRF(session.value.csrf_token);company.value=session.value.companies[0]?.name||'';date.value=session.value.today;month.value=date.value.slice(0,7);calendarYear.value=Number(date.value.slice(0,4));tab.value=tabs.value[0]?.id||'setup';if(company.value){await loadCatalog();await load()}}catch(e){error.value=e.message}finally{busy.value=false}}
async function changeCompany(){farm.value='';shift.value='';staff.value=[];await loadCatalog();await load()}
function chooseTab(value){if(dirty.value){error.value='Lưu hoặc bỏ thay đổi bảng công trước khi chuyển màn hình.';return}tab.value=value;notice.value='';load()}
function edit(row){row.selected=true;row.edited=true}
function chooseStatus(row){row.working_hours=row.status==='Half Day'?4:row.status==='Absent'?0:8;if(row.status==='Absent')row.overtime_hours=0;edit(row)}
function markPresent(){for(const row of staff.value)if(row.docstatus===0&&row.status!=='On Leave'){row.status='Present';chooseStatus(row)}}
// Fills unsaved rows from device check-ins; the manager still reviews, saves and submits.
async function fromMachine(){machineBusy.value=true;error.value=''
 try{const result=await api('propose_from_checkins',{company:company.value,date:date.value,shift:shift.value});const proposals=new Map(result.rows.map(r=>[r.employee,r]));let applied=0,review=0
  for(const row of staff.value){const p=proposals.get(row.employee);if(!p||row.docstatus!==0||row.status==='On Leave')continue
   row.machine=p;if(p.needs_review){review++;continue}if(!p.status)continue
   Object.assign(row,{status:p.status,working_hours:p.working_hours,overtime_hours:p.overtime_hours,in_time:p.in_time,out_time:p.out_time,late_entry:p.late_entry,early_exit:p.early_exit});edit(row);applied++}
  notice.value='Đã điền '+applied+' dòng từ '+result.checkins+' lượt chấm'+(review?'; '+review+' dòng thiếu lượt chấm cần kiểm tra':'')+'. Kiểm tra rồi bấm Lưu nháp.'
 }catch(e){error.value=e.message}finally{machineBusy.value=false}}
// The saved list is rebuilt from these inputs, so existing holidays are loaded back as editable rows.
function loadCalendarForm(info){const weekly=[...new Set(info.holidays.filter(h=>h.weekly_off).map(h=>info.weekdays[(new Date(h.date+'T00:00:00').getDay()+6)%7]))];weeklyOff.value=weekly.length?weekly:['Sunday'];extraHolidays.value=info.holidays.filter(h=>!h.weekly_off).map(h=>({date:h.date,description:h.description}))}
async function saveCalendar(){saving.value=true;error.value='';try{const result=await periodApi('setup_calendar',{company:company.value,year:calendarYear.value,weekly_off:weeklyOff.value,extra:extraHolidays.value.filter(h=>h.date)},true);notice.value='Đã lưu lịch nghỉ '+calendarYear.value+': '+result.days+' ngày nghỉ.';await loadCatalog();await load()}catch(e){error.value=e.message}finally{saving.value=false}}
async function saveStaff(){const rows=selected.value.filter(r=>r.docstatus===0&&r.status&&r.status!=='On Leave');if(!rows.length){error.value='Chọn nhân viên và trạng thái để lưu nháp.';return}saving.value=true;error.value='';try{await api('save_staff',{company:company.value,date:date.value,shift:shift.value,client_event_id:eventId.value,rows:rows.map(r=>({employee:r.employee,name:r.name,modified:r.modified,status:r.status,working_hours:r.working_hours,overtime_hours:r.overtime_hours||0,in_time:r.in_time||null,out_time:r.out_time||null,late_entry:r.late_entry?1:0,early_exit:r.early_exit?1:0,note:r.note}))},true);notice.value='Đã lưu '+rows.length+' dòng công nháp.';await load()}catch(e){error.value=e.message}finally{saving.value=false}}
async function askStaff(action){const rows=selected.value;if(!rows.length||rows.some(r=>r.edited||!r.name||r.docstatus!==(action==='cancel'?1:0))){error.value='Chọn các phiếu '+(action==='cancel'?'đã duyệt':'nháp đã lưu')+' phù hợp thao tác. Lưu thay đổi trước khi duyệt.';return}confirmation.value={type:'staff',action,rows:rows.map(r=>({name:r.name,modified:r.modified}))};reason.value='';await nextTick();confirmDialog.value.showModal()}
async function askCrew(row,action){if(action==='submit'&&crewSnapshot()!==crewBaseline.value){error.value='Lưu thay đổi trước khi duyệt phiếu công.';return}confirmation.value={type:'crew',action,name:row.name,modified:row.modified};reason.value='';await nextTick();confirmDialog.value.showModal()}
async function act(){saving.value=true;error.value='';try{const item=confirmation.value;await api(item.type==='staff'?'staff_action':'crew_action',{company:company.value,...item,reason:reason.value},true);confirmDialog.value.close();if(item.type==='crew')crewDialog.value.close();notice.value=item.action==='submit'?'Đã duyệt bảng công.':item.action==='cancel'?'Đã hủy phiếu công.':'Đã xóa phiếu nháp.';await load()}catch(e){error.value=e.message}finally{saving.value=false}}
async function openCrew(row=null){error.value='';Object.assign(crew,{name:null,modified:null,farm:farm.value||catalog.value.farms[0]?.name||'',work_team:'',posting_date:date.value,headcount:0,present:0,workdays:0,completed_qty:0,uom:'',unit_rate:0,work_type:'',listed_piecework_rate:0,rate_override_reason:'',notes:'',client_event_id:crypto.randomUUID()},row||{});crewBaseline.value=crewSnapshot();await nextTick();crewDialog.value.showModal()}
function setTeam(){const team=catalog.value.teams.find(t=>t.name===crew.work_team);if(team)crew.farm=team.farm}
function setWork(){const work=(catalog.value.works||[]).find(w=>w.name===crew.work_type);if(work){crew.uom=work.uom;crew.listed_piecework_rate=Number(work.piecework_rate||0);crew.unit_rate=crew.listed_piecework_rate;crew.rate_override_reason=''}}
async function saveCrew(){saving.value=true;error.value='';try{const {client_event_id,...values}=crew;await api('save_crew',{company:company.value,values,client_event_id},true);crewDialog.value.close();notice.value='Đã lưu phiếu công đội khoán nháp.';await load()}catch(e){error.value=e.message}finally{saving.value=false}}
async function openMaster(kind){error.value='';masterKind.value=kind;for(const key of Object.keys(master))delete master[key];Object.assign(master,kind==='employee'?{employee_name:'',gender:'',date_of_birth:'',date_of_joining:date.value,designation:'',department:''}:kind==='team'?{farm:farm.value||catalog.value.farms[0]?.name||'',name:'',code:'',foreman:'',phone:''}:kind==='shift'?{name:'',start_time:'07:00',end_time:'16:00',late_grace:10,early_grace:10,half_day_hours:6,absent_hours:2}:{code:'',name:''});await nextTick();masterDialog.value.showModal()}
async function saveMaster(){saving.value=true;error.value='';try{if(masterKind.value==='farm')await api('create_farm',{company:company.value,...master},true);else if(masterKind.value==='shift')await api('create_shift',{...master,company:company.value},true);else await api(masterKind.value==='employee'?'create_employee':'create_team',{company:company.value,values:{...master}},true);masterDialog.value.close();notice.value='Đã tạo '+({employee:'nhân viên',team:'đội khoán',farm:'vườn',shift:'ca làm việc'})[masterKind.value]+'.';await loadCatalog();await load()}catch(e){error.value=e.message}finally{saving.value=false}}
const crewColumns=[{field:'work_team',headerName:'Đội khoán',minWidth:190,valueFormatter:p=>teamName(p.value)},{field:'work_type',headerName:'Công việc',minWidth:170,valueFormatter:p=>(catalog.value.works||[]).find(w=>w.name===p.value)?.work_name||p.value||'Cũ'},{field:'foreman',headerName:'Đầu câu',minWidth:140},{field:'headcount',headerName:'Tổng người',minWidth:100},{field:'present',headerName:'Có mặt',minWidth:85},{field:'workdays',headerName:'Tổng công',minWidth:100,valueFormatter:p=>fmt(p.value)},{field:'amount',headerName:'Giá trị khoán',minWidth:140,valueFormatter:p=>cash(p.value)},{field:'docstatus',headerName:'Trạng thái',minWidth:110,valueFormatter:p=>state(p.value)}]
const teamColumns=[{field:'team_name',headerName:'Đội khoán',minWidth:190},{field:'lotus_foreman',headerName:'Đầu câu',minWidth:150},{field:'lotus_foreman_phone',headerName:'Điện thoại',minWidth:140},{field:'farm',headerName:'Vườn',minWidth:160,valueFormatter:p=>farmName(p.value)}]
function monthlyRows(data,kind){return (data?.rows||[]).map(row=>({...row,label:kind==='staff'?row.employee_name:row.team_name,...Object.fromEntries(Array.from({length:data.days},(_,i)=>['d'+(i+1),(row.days[String(i+1)]||[]).map(r=>(r.docstatus===0?'*':'')+(kind==='staff'?(statusCode[r.status]||'—'):fmt(r.workdays))).join('/')||'—']))}))}
function monthColumns(data,kind){return [{field:'label',headerName:kind==='staff'?'Nhân viên':'Đội khoán',minWidth:200,pinned:'left'},...Array.from({length:data?.days||0},(_,i)=>({field:'d'+(i+1),headerName:String(i+1),minWidth:55})),{field:'workdays',headerName:'Công đã duyệt',minWidth:120,valueFormatter:p=>fmt(p.value)},...(kind==='staff'?[{field:'working_hours',headerName:'Giờ làm',minWidth:100},{field:'overtime_hours',headerName:'Giờ tăng ca',minWidth:110}]:[{field:'amount',headerName:'Giá trị khoán',minWidth:145,valueFormatter:p=>cash(p.value)}]),{field:'draft_count',headerName:'Phiếu nháp',minWidth:105}]}
const printLink=kind=>'/lotus/in-cong?'+new URLSearchParams({company:company.value,month:month.value,kind,...(farm.value&&kind==='crew'?{farm:farm.value}:{})})
const exportLink=kind=>'/api/method/lotus_farm.timekeeping.export_month?'+new URLSearchParams({company:company.value,month:month.value,kind,...(farm.value&&kind==='crew'?{farm:farm.value}:{})})
onMounted(init)
// Success messages show as toasts (errors stay inline next to the form).
useNoticeToast(notice)
</script>

<template><div class="stock-shell attendance-shell lotus-ui" :class="{'embedded-workspace':embedded,'sidebar-collapsed':sidebarCollapsed}">
 
 <component :is="embedded?'section':'main'" class="stock-main"><WorkspaceTabs v-if="embedded" :items="tabs" :model-value="tab" @update:model-value="chooseTab($event)"/>
  <p v-if="error" class="stock-error" role="alert">{{error}}</p>
  <div class="stock-scope"><label v-if="(session?.companies?.length||0)>1">Công ty<UiSelect v-model="company" :disabled="busy||saving||dirty" @change="changeCompany"><option v-for="c in session?.companies" :key="c.name">{{c.name}}</option></UiSelect></label><label v-if="tab!=='month'">Ngày công<UiInput v-model="date" type="date" :max="session?.today" :disabled="busy||saving||dirty" @change="load"/></label><label v-else>Tháng<UiInput v-model="month" type="month" :disabled="busy||saving" @change="load"/></label><label v-if="tab==='staff'">Ca làm việc<UiSelect v-model="shift" :disabled="busy||saving||dirty" @change="load"><option value="">Không phân ca</option><option v-for="s in catalog.shifts" :key="s.name">{{s.name}}</option></UiSelect></label><label v-if="['crew','month','setup'].includes(tab)">Vườn<UiSelect v-model="farm" :disabled="busy||saving" @change="load"><option value="">Tất cả được phân quyền</option><option v-for="f in catalog.farms" :key="f.name" :value="f.name">{{f.farm_name}}</option></UiSelect></label><UiButton variant="outline" :disabled="busy||saving||dirty" @click="load">{{busy?'Đang tải…':'Làm mới'}}</UiButton></div>
  <template v-if="tab==='staff'">
   <p v-if="locked" class="attendance-notice" role="status">Tháng {{date.slice(0,7)}} đã khóa công. Chỉ xem; HR Manager mở lại kỳ ở Nhân sự › Cấu hình lương.</p>
   <p v-else-if="dayInfo.holiday" class="attendance-notice" role="status">{{dayInfo.holiday.weekly_off?'Ngày nghỉ hằng tuần':'Ngày lễ: '+dayInfo.holiday.description}}. Làm việc ngày này được tính hệ số ngày nghỉ trong bảng lương.</p>
   <p v-else-if="!dayInfo.has_calendar" class="attendance-notice" role="status">Công ty chưa có lịch nghỉ năm này. Tạo ở tab Nhân sự & thiết lập để tính công chuẩn và khóa kỳ.</p>
   <div class="attendance-toolbar"><strong>{{staffCounts.people}} nhân viên</strong><span>{{staffCounts.approved}} đã duyệt · {{staffCounts.pending}} nháp · {{staffCounts.unknown}} chưa chấm</span><UiButton v-if="cap.Attendance?.create&&session?.can_read_checkins&&!locked" variant="outline" :disabled="machineBusy||saving||busy" @click="fromMachine">{{machineBusy?'Đang đọc máy…':'Lấy công từ máy chấm'}}</UiButton><UiButton v-if="cap.Attendance?.create&&!locked" variant="outline" @click="markPresent">Có mặt tất cả</UiButton><UiButton v-if="canEditStaff" :disabled="saving||busy" @click="saveStaff">Lưu nháp</UiButton><UiButton v-if="cap.Attendance?.submit&&!locked" variant="outline" :disabled="saving" @click="askStaff('submit')">Duyệt đã chọn</UiButton><UiButton v-if="cap.Attendance?.cancel&&!locked" variant="outline" :disabled="saving" @click="askStaff('cancel')">Hủy đã duyệt</UiButton><UiButton v-if="cap.Attendance?.delete&&!locked" variant="outline" :disabled="saving" @click="askStaff('delete')">Xóa nháp</UiButton><UiButton v-if="dirty" variant="outline" @click="load">Bỏ thay đổi</UiButton></div>
   <section class="stock-panel attendance-roster"><table><thead><tr><th><input type="checkbox" aria-label="Chọn tất cả nhân viên" @change="staff.forEach(r=>r.selected=$event.target.checked)"></th><th>Nhân viên</th><th>Bộ phận / chức vụ</th><th>Trạng thái công</th><th>Giờ làm</th><th>Tăng ca</th><th>Máy chấm</th><th>Ghi chú</th><th>Phiếu</th></tr></thead><tbody><tr v-for="row in staff" :key="row.employee" :class="{'attendance-review':row.machine?.needs_review}"><td><input v-model="row.selected" type="checkbox" :aria-label="'Chọn '+row.employee_name"></td><td><strong>{{row.employee_name}}</strong><small>{{row.employee}}</small></td><td>{{row.designation||row.department||'—'}}</td><td><UiSelect v-model="row.status" :aria-label="'Trạng thái '+row.employee_name" :disabled="saving||row.docstatus===1||row.status==='On Leave'||!canEditStaff" @change="chooseStatus(row)"><option value="">Chưa chấm</option><option v-if="row.status==='On Leave'" value="On Leave">Nghỉ phép (HRMS)</option><option v-for="[value,label] in editableStatuses" :key="value" :value="value">{{label}}</option></UiSelect></td><td><UiInput v-model.number="row.working_hours" type="number" min="0" max="24" step="0.25" :aria-label="'Giờ làm '+row.employee_name" :disabled="saving||row.docstatus===1||row.status==='On Leave'||!canEditStaff" @input="edit(row)"/></td><td><UiInput v-model.number="row.overtime_hours" type="number" min="0" max="16" step="0.25" :aria-label="'Giờ tăng ca '+row.employee_name" :disabled="saving||row.docstatus===1||['On Leave','Absent'].includes(row.status)||!canEditStaff" @input="edit(row)"/></td><td><span>{{machineText(row)||(row.in_time?clock(row.in_time)+'–'+clock(row.out_time):'—')}}</span><small v-if="row.machine?.needs_review">Cần kiểm tra</small></td><td><UiInput v-model="row.note" :aria-label="'Ghi chú '+row.employee_name" :disabled="saving||row.docstatus===1||!canEditStaff" @input="edit(row)"/></td><td><span :class="row.docstatus===1?'attendance-approved':''">{{row.name?state(row.docstatus):'Chưa chấm'}}</span><small v-if="row.edited">Chưa lưu</small></td></tr></tbody></table><p v-if="!staff.length&&!busy" class="stock-empty">Chưa có nhân viên trong công ty này.<UiButton v-if="cap.Employee?.create" variant="link" @click="openMaster('employee')">Thêm nhân sự chủ chốt</UiButton></p></section>
  </template>
  <template v-if="tab==='crew'"><div class="attendance-toolbar"><UiButton v-if="cap['Lotus Crew Attendance']?.create" :disabled="!availableTeams.length||saving" @click="openCrew()">+ Phiếu công đội khoán</UiButton><UiButton v-if="cap['Work Team']?.create" variant="outline" @click="openMaster('team')">+ Đội / đầu câu</UiButton><span>{{crews.length}} phiếu ngày {{date}}</span></div><section class="stock-panel"><DataTable :rows="crews" :columns="crewColumns" :loading="busy" interactive @open="openCrew" empty="Chưa có phiếu công đội khoán trong ngày."/></section></template>
  <template v-if="tab==='month'">
   <section v-if="monthData" class="stock-panel attendance-month"><div class="attendance-toolbar"><strong>Nhân sự chính thức · {{month}}</strong><span v-if="monthData.period_closed" class="attendance-approved">Đã khóa kỳ</span><a v-if="cap.Attendance?.print" class="stock-button" :href="printLink('staff')" target="_blank" rel="noopener">In bảng công</a><a v-if="cap.Attendance?.export" class="stock-button" :href="exportLink('staff')">Xuất CSV</a></div><DataTable :rows="monthlyRows(monthData,'staff')" :columns="monthColumns(monthData,'staff')" :loading="busy"/><p class="attendance-legend">X: Có mặt · ½: Nửa ngày · V: Vắng · TX: Từ xa · P: Nghỉ phép · *: Nháp, chưa tính tổng · —: Chưa chấm</p></section>
   <section v-if="crewMonth" class="stock-panel attendance-month"><div class="attendance-toolbar"><strong>Đội khoán · {{month}}</strong><a v-if="cap['Lotus Crew Attendance']?.print" class="stock-button" :href="printLink('crew')" target="_blank" rel="noopener">In bảng công</a><a v-if="cap['Lotus Crew Attendance']?.export" class="stock-button" :href="exportLink('crew')">Xuất CSV</a></div><DataTable :rows="monthlyRows(crewMonth,'crew')" :columns="monthColumns(crewMonth,'crew')" :loading="busy"/><p class="attendance-legend">Mỗi ô là tổng công đội trong ngày · *: Nháp, chưa tính tổng · Giá trị khoán chưa phải chứng từ thanh toán</p></section>
  </template>
  <template v-if="tab==='setup'"><div class="attendance-toolbar"><UiButton v-if="cap.Employee?.create" @click="openMaster('employee')">+ Nhân sự chính thức</UiButton><UiButton v-if="cap['Work Team']?.create" variant="outline" @click="openMaster('team')">+ Đội khoán / đầu câu</UiButton><UiButton v-if="session?.can_create_farm" variant="outline" @click="openMaster('farm')">+ Vườn</UiButton><UiButton v-if="cap.Attendance?.create" variant="outline" @click="openMaster('shift')">+ Ca làm việc</UiButton><a class="stock-button" href="/lotus/nhan-su">Hồ sơ nhân sự, tuyển dụng & tiếp nhận ↗</a><a class="stock-button" href="/desk/hr-setup">HRMS · Quản trị nhân sự ↗</a></div><section class="stock-panel"><DataTable :rows="catalog.teams" :columns="teamColumns" empty="Chưa có đội khoán được phân quyền."/></section>
   <section v-if="session?.is_hr_manager" class="stock-panel attendance-calendar" aria-label="Lịch nghỉ năm"><div class="attendance-toolbar"><strong>Lịch nghỉ năm</strong><label>Năm<UiInput v-model.number="calendarYear" type="number" min="2020" max="2100" :disabled="busy||saving" @change="load"/></label><span>{{calendarInfo?.name?(calendarInfo.is_default?'Đang dùng cho công ty':'Đã tạo, chưa là lịch mặc định'):'Chưa tạo lịch năm này'}}</span></div>
    <fieldset class="attendance-weekdays"><legend>Nghỉ hằng tuần</legend><label v-for="day in calendarInfo?.weekdays||[]" :key="day"><input v-model="weeklyOff" type="checkbox" :value="day" :disabled="saving">{{weekdayLabels[day]}}</label></fieldset>
    <table class="attendance-holidays"><thead><tr><th>Ngày lễ</th><th>Tên</th><th></th></tr></thead><tbody><tr v-for="(h,i) in extraHolidays" :key="'x'+i"><td><UiInput v-model="h.date" type="date" :aria-label="'Ngày lễ thêm '+(i+1)" :disabled="saving"/></td><td><UiInput v-model="h.description" maxlength="140" placeholder="VD: Tết Nguyên đán" :aria-label="'Tên ngày lễ '+(i+1)" :disabled="saving"/></td><td><UiButton variant="outline" size="sm" :disabled="saving" @click="extraHolidays.splice(i,1)">Bỏ</UiButton></td></tr></tbody></table>
    <div class="attendance-toolbar"><UiButton variant="outline" :disabled="saving" @click="extraHolidays.push({date:'',description:''})">+ Ngày lễ</UiButton><UiButton :disabled="saving||busy" @click="saveCalendar">{{calendarInfo?.name?'Cập nhật lịch':'Tạo lịch năm'}}</UiButton><span>1/1, 30/4, 1/5, 2/9 tự thêm. Tết, Giỗ tổ và ngày liền kề 2/9 đổi theo năm: thêm tay.</span></div></section><p class="attendance-legend">Nhân sự chủ chốt dùng hồ sơ Employee và Attendance của HRMS. Đội khoán do đầu câu phụ trách, theo dõi tổng người, tổng công và khối lượng riêng.</p></template>
 </component>
 <WorkspaceModal bare title="Phiếu công đội khoán" :busy="saving" ref="crewDialog" class="stock-dialog"><form @submit.prevent="saveCrew"><header><h2>Phiếu công đội khoán</h2><UiButton type="button" variant="outline" :disabled="saving" aria-label="Đóng phiếu công đội" @click="crewDialog.close()">✕</UiButton></header><p v-if="error" class="stock-error" role="alert">{{error}}</p><div class="attendance-form"><label>Đội khoán<UiSelect v-model="crew.work_team" required :disabled="!!crew.name||saving" @change="setTeam"><option value="">Chọn đội</option><option v-for="team in catalog.teams" :key="team.name" :value="team.name">{{team.team_name}} · {{team.lotus_foreman}}</option></UiSelect></label><label>Ngày công<UiInput v-model="crew.posting_date" type="date" required :max="session?.today" :disabled="!!crew.name||saving"/></label><label>Công việc khoán<UiSelect v-model="crew.work_type" :disabled="!!crew.name||crew.docstatus===1||saving" @change="setWork"><option value="">Chọn công việc</option><option v-for="w in catalog.works||[]" :key="w.name" :value="w.name">{{w.work_name}}</option></UiSelect></label><label>Tổng người<UiInput v-model.number="crew.headcount" type="number" min="0" step="1" required :disabled="crew.docstatus===1||saving"/></label><label>Có mặt<UiInput v-model.number="crew.present" type="number" min="0" :max="crew.headcount" step="1" required :disabled="crew.docstatus===1||saving"/></label><label>Tổng công<UiInput v-model.number="crew.workdays" type="number" min="0" :max="crew.present" step="0.25" required :disabled="crew.docstatus===1||saving"/></label><label>Khối lượng khoán<UiInput v-model.number="crew.completed_qty" type="number" min="0" step="any" :disabled="crew.docstatus===1||saving"/></label><label>Đơn vị khoán<UiSelect v-model="crew.uom" :required="crew.completed_qty>0" :disabled="crew.docstatus===1||saving||!!crew.work_type"><option value="">Chọn đơn vị</option><option v-for="unit in catalog.uoms" :key="unit.name" :value="unit.name">{{unitLabel(unit.name)}}</option></UiSelect></label><label>Đơn giá khoán ({{currency}})<UiInput v-model.number="crew.unit_rate" type="number" min="0" step="any" :disabled="crew.docstatus===1||saving"/></label><label v-if="crew.work_type">Đơn giá niêm yết: <strong>{{cash(crew.listed_piecework_rate)}} / {{unitLabel(crew.uom)}}</strong></label><label v-if="crew.work_type&&Number(crew.unit_rate)!==Number(crew.listed_piecework_rate)">Lý do điều chỉnh đơn giá<UiTextarea v-model="crew.rate_override_reason" required :disabled="crew.docstatus===1||saving"/></label></div><label>Ghi chú<UiTextarea v-model="crew.notes" :disabled="crew.docstatus===1||saving" maxlength="2000"/></label><p>Giá trị khoán <strong>{{cash(Number(crew.completed_qty||0)*Number(crew.unit_rate||0))}}</strong></p><footer><UiButton v-if="crew.docstatus!==1&&(crew.name?cap['Lotus Crew Attendance']?.write:cap['Lotus Crew Attendance']?.create)" type="submit" :disabled="saving">Lưu nháp</UiButton><UiButton v-if="crew.name&&crew.docstatus===0&&cap['Lotus Crew Attendance']?.submit" type="button" variant="outline" :disabled="saving" @click="askCrew(crew,'submit')">Duyệt phiếu</UiButton><UiButton v-if="crew.name&&crew.docstatus===1&&cap['Lotus Crew Attendance']?.cancel" type="button" variant="outline" :disabled="saving" @click="askCrew(crew,'cancel')">Hủy đã duyệt</UiButton><UiButton v-if="crew.name&&crew.docstatus===0&&cap['Lotus Crew Attendance']?.delete" type="button" variant="destructive" :disabled="saving" @click="askCrew(crew,'delete')">Xóa nháp</UiButton></footer></form></WorkspaceModal>
 <WorkspaceModal bare title="Danh mục chấm công" :busy="saving" ref="masterDialog" class="stock-dialog"><form @submit.prevent="saveMaster"><header><h2>{{{employee:'Thêm nhân sự chính thức',team:'Đội khoán / đầu câu',farm:'Thêm vườn',shift:'Thêm ca làm việc'}[masterKind]}}</h2><UiButton type="button" variant="outline" :disabled="saving" aria-label="Đóng thiết lập" @click="masterDialog.close()">✕</UiButton></header><p v-if="error" class="stock-error" role="alert">{{error}}</p><div class="attendance-form"><template v-if="masterKind==='employee'"><label>Họ tên<UiInput v-model="master.employee_name" required maxlength="140"/></label><label>Giới tính<UiSelect v-model="master.gender" required><option value="">Chọn giới tính</option><option v-for="gender in catalog.genders" :key="gender.name" :value="gender.name">{{genderLabel(gender.name)}}</option></UiSelect></label><label>Ngày sinh<UiInput v-model="master.date_of_birth" type="date" :max="session?.today" required/></label><label>Ngày vào làm<UiInput v-model="master.date_of_joining" type="date" required/></label><label>Chức vụ<UiInput v-model="master.designation" maxlength="140" placeholder="VD: Giám đốc, quản lý farm, kế toán…"/></label><label>Bộ phận<UiSelect v-model="master.department"><option value="">Chưa phân bộ phận</option><option v-for="department in catalog.departments" :key="department.name" :value="department.name">{{department.department_name}}</option></UiSelect></label></template><template v-else-if="masterKind==='team'"><label>Vườn<UiSelect v-model="master.farm" required><option value="">Chọn vườn</option><option v-for="f in catalog.farms" :key="f.name" :value="f.name">{{f.farm_name}}</option></UiSelect></label><label>Mã đội<UiInput v-model="master.code" required maxlength="140"/></label><label>Tên đội<UiInput v-model="master.name" required maxlength="140"/></label><label>Đầu câu / người phụ trách<UiInput v-model="master.foreman" required maxlength="140"/></label><label>Điện thoại<UiInput v-model="master.phone" maxlength="40"/></label></template><template v-else-if="masterKind==='shift'"><label>Tên ca<UiInput v-model="master.name" required maxlength="140"/></label><label>Giờ bắt đầu<UiInput v-model="master.start_time" type="time" required/></label><label>Giờ kết thúc<UiInput v-model="master.end_time" type="time" required/></label><label>Cho phép đi muộn (phút)<UiInput v-model.number="master.late_grace" type="number" min="0" max="240" step="1"/></label><label>Cho phép về sớm (phút)<UiInput v-model.number="master.early_grace" type="number" min="0" max="240" step="1"/></label><label>Dưới số giờ này tính nửa ngày<UiInput v-model.number="master.half_day_hours" type="number" min="0" max="24" step="0.5"/></label><label>Dưới số giờ này tính vắng<UiInput v-model.number="master.absent_hours" type="number" min="0" max="24" step="0.5"/></label></template><template v-else><label>Mã vườn<UiInput v-model="master.code" required maxlength="140" placeholder="FARM-222"/></label><label>Tên vườn<UiInput v-model="master.name" required maxlength="140" placeholder="Farm 222 Thuận Phú"/></label></template></div><footer><UiButton type="submit" :disabled="saving">{{saving?'Đang lưu…':'Tạo mới'}}</UiButton></footer></form></WorkspaceModal>
 <WorkspaceModal bare title="Xác nhận bảng công" :busy="saving" ref="confirmDialog" class="stock-dialog"><form @submit.prevent="act"><header><h2>{{confirmation?.action==='submit'?'Duyệt công':confirmation?.action==='cancel'?'Hủy công đã duyệt':'Xóa công nháp'}}</h2><UiButton type="button" variant="outline" :disabled="saving" aria-label="Đóng xác nhận công" @click="confirmDialog.close()">✕</UiButton></header><p v-if="error" class="stock-error" role="alert">{{error}}</p><p v-if="confirmation?.type==='staff'">{{confirmation.rows.length}} phiếu công đã chọn</p><label v-if="confirmation?.action==='cancel'">Lý do hủy<UiTextarea v-model="reason" required maxlength="2000"/></label><footer><UiButton type="button" variant="outline" :disabled="saving" @click="confirmDialog.close()">Quay lại</UiButton><UiButton type="submit" :disabled="saving">Xác nhận</UiButton></footer></form></WorkspaceModal>
</div></template>
